import{_ as t,C as d,o as c,c as r,E as s,a2 as n}from"./chunks/framework.BXyf8PVu.js";const S=JSON.parse('{"title":"Musico","description":"","frontmatter":{"pageClass":"project-case-study","title":"Musico","order":5},"headers":[],"relativePath":"jp/projects/musico.md","filePath":"jp/projects/musico.md"}'),i={name:"jp/projects/musico.md"};function a(g,o,l,u,p,h){const e=d("ProjectHero");return c(),r("div",null,[s(e,{index:"05",eyebrow:"ソフトウェア工学 · ネイティブオーディオ",title:"Musico：ネイティブ・オフライン音楽プレーヤー",summary:"Apple、Android、Windows 向けにそれぞれ 100% ネイティブで構築された、フォルダ指向・マルチキュー対応のローカル音楽プレーヤー。Web ラッパーを使わず、共通の JavaScript 拡張ランタイムを備えています。",year:"2025–2026",role:"アーキテクチャ設計・ネイティブ UI・オーディオ実装",methods:"SwiftUI · Jetpack Compose · .NET 8 WPF · JavaScriptCore / QuickJS / Jint",chart:"/charts/musico-architecture.html?lang=ja","image-alt":"Apple・Android・Windows ネイティブクライアント間における Musico のインタラクティブ構成図",docs:"https://musico.seanpnex.win/?lang=ja",repo:"https://github.com/SEANPNEX/Musico"}),o[0]||(o[0]=n('<h2 id="問い" tabindex="-1">問い <a class="header-anchor" href="#問い" aria-label="Permalink to &quot;問い&quot;">​</a></h2><p>現代のクロスプラットフォームのデスクトップ／モバイルアプリの多くは Electron や組み込み WebView を採用し、単一 UI 層の代わりにメモリ消費量やネイティブ音声パイプライン、OS との統合性を犠牲にしています。一方で、ローカル音源を大切に管理するリスナーにとって重要なのは、ストリーミングアプリが無視しがちな 2 つの点――<strong>フォルダ階層を崩さないこと</strong>と、<strong>再生位置を失わずに複数の独立した再生キューを行き来できること</strong>です。</p><p><strong>Musico</strong> はその逆のトレードオフを追求しました。<strong>Musicolet</strong> と <strong>YRRLYB/Aria</strong> に着想を得て、Apple、Android、Windows それぞれに向けて心地よいフォルダ指向オフライン音楽プレーヤーを <strong>100% ネイティブ</strong> で構築しつつ、ライブラリモデル、再生セマンティクス、カスタム音源拡張の仕組みを全プラットフォームで統一しています。</p><h2 id="web-ラッパーなしの-3-つのネイティブクライアント" tabindex="-1">Web ラッパーなしの 3 つのネイティブクライアント <a class="header-anchor" href="#web-ラッパーなしの-3-つのネイティブクライアント" aria-label="Permalink to &quot;Web ラッパーなしの 3 つのネイティブクライアント&quot;">​</a></h2><p>各プラットフォームのクライアントはそれぞれのエコシステム固有の UI ツールキット・オーディオエンジン・システムメディア連携を採用し、拡張機能向けに軽量な JavaScript エンジンを組み込んでいます：</p><table tabindex="0"><thead><tr><th>クライアント</th><th>対象プラットフォーム</th><th>技術スタック</th><th>ネイティブデザインと OS 連携</th></tr></thead><tbody><tr><td><code>Musico/</code></td><td>iOS 17+、iPadOS、macOS (Catalyst)</td><td>Swift、SwiftUI（<code>@Observable</code>）、<code>AVAudioEngine</code> + <code>AVAudioUnitEQ</code>、<code>MPNowPlayingInfoCenter</code>、<code>JavaScriptCore</code>（<code>Compression</code> + <code>CryptoKit</code>）</td><td>Apple HIG — iOS のタブ／シート構成、スワイプ操作（フォルダ誤削除を防ぐ <code>allowsFullSwipe: false</code> およびキュー／プレイリストのスワイプ削除 <strong>元に戻す（Undo）</strong>）；macOS の <code>NSVisualEffectView</code> すりガラス半透明、独立したサイドバー色、<code>Cmd+K</code> コマンドパレット、フローティング・ミニプレーヤー、ドラッグ＆ドロップ対応</td></tr><tr><td><code>MusicoAndroid/</code></td><td>Android 8.0+ (API 26+)</td><td>Kotlin、Jetpack Compose、AndroidX Media3（ExoPlayer + <code>MediaSessionService</code>）、SAF <code>DocumentFile</code>、<code>DynamicsProcessing</code> EQ、<code>QuickJS</code>（<code>quickjs-kt</code>）</td><td>Material 3 / Material You — Dynamic Color、可変 <code>NavigationBar</code> / <code>NavigationRail</code>、<code>ModalBottomSheet</code>、Outlook × Material You の 2 段階 <code>MusicoSwipeActionRow</code> スワイプ操作（きれいにクリップされた背面レール、触覚ディテント、<code>≡</code> ハンドルが引っかからない <code>DragReorder</code> ハンドルのスワイプ排他ロック）、選択チェックマークが窮屈にならない 1 行セグメントピッカー、キュー <strong>Undo</strong> 付きのダークテーマ <code>MusicoSnackbarHost</code> スナックバー、カスタム外観テーマ、端末／<code>Musico</code> フォルダ削除対応</td></tr><tr><td><code>MusicoWindows/</code></td><td>Windows 10 (2004+)・Windows 11</td><td>C# / .NET 8 WPF、NAudio（<code>BiQuadFilter</code> 10 バンド EQ）、TagLibSharp、Windows 10 SMTC、<code>Jint</code></td><td>Fluent Design — Windows 11 DWM 角丸／背景＆Acrylic、独立したサイドバー色と不透明度、<code>Ctrl+K</code> コマンドパレット、フローティング・ミニプレーヤー、ドラッグ＆ドロップ対応</td></tr></tbody></table><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to &quot;主な機能&quot;">​</a></h2><ul><li><strong>フォルダ指向ライブラリ・ドラッグ＆ドロップ・安全な削除：</strong> 元のディレクトリ階層を保ったままローカルフォルダ（<code>Music</code>、<code>Documents</code>、または任意のフォルダ）をマウントできるほか、macOS/Windows ではフォルダや音声ファイルをウィンドウへ直接ドラッグ＆ドロップできます（ドロップしたフォルダは <strong>フォルダ</strong> にマウントされ、曲は即座に再生し、ライブラリ外のファイルは既定の音楽フォルダへコピー）。ドライブを取り外したりフォルダを移動しても、<strong>再配置（Relocate）</strong> でプレイリストや再生履歴を失わずに再接続できます。削除操作は <strong>ライブラリから削除</strong> とディスク上の削除（macOS の <strong>ゴミ箱に入れる</strong>、Windows の <strong>ごみ箱に移動</strong>、iOS/Android の Android <code>Musico</code> フォルダを含む <strong>端末から削除</strong>）を明確に分離。FLAC、ALAC、WAV、AIFF、MP3、AAC/M4A（プラットフォームにより OGG、Opus、WMA、WebM）のロスレス／ロッシー再生に幅広く対応します。</li><li><strong>クラウドフォルダ・任意の Drive OAuth 2.0・オフライン同期：</strong> 公開または Cookie 認証ソースを <strong>フォルダ</strong> 内に直接マウント可能――<strong>YouTube / YouTube Music</strong>（プレイリスト、<code>RD</code> ミックス、アルバム、単曲）、<strong>Bilibili</strong>（<code>BV</code>/<code>av</code> マルチパート動画、<code>favlist</code>、コレクション）、<strong>Google Drive</strong>（再帰的フォルダ探索と単一ファイル）に対応します。公開／共有 Drive リンクはログイン不要で利用でき、非公開フォルダや大容量ファイルのダウンロード回避には、任意の <strong>設定 → Google Drive アカウント</strong> にユーザー自身の無料デスクトップアプリ用 OAuth 2.0 クライアント ID（<code>drive.readonly</code> + <code>userinfo.email</code>、テストモード、自動 <code>http://127.0.0.1:&lt;port&gt;/oauth2callback</code>、<strong>Google Drive に再接続</strong> 付き 7 日間テストトークン）を設定できます。トラックは <code>.musico-cloud.json</code> マニフェストとともにローカルへ保存し、<strong>クラウドから更新</strong> で差分取得できます。</li><li><strong>複数の独立した再生キュー・重複排除 <code>Play Next</code>・モバイルスワイプ操作：</strong> 気分や聴くシーンに合わせて並列キューを立ち上げ、いつでもリネーム・並び替え・クリア・切り替えが可能。各キューが現在のトラック、再生位置、シャッフル順、リピートモード（<code>Off</code> / <code>All</code> / <code>One</code>）を個別に保持します。Apple・Android・Windows 共通の <strong>重複排除 <code>Play Next</code></strong>（<code>insertNext</code>）は、曲を複製する代わりにキュー内の再生中以外の既存エントリをきれいに移動し、再生中の曲には影響を与えません。プラットフォーム間で統一されたモバイルスワイプ操作では、右スワイプで <strong>次に再生（Play Next）</strong>、<strong>ライブラリ曲</strong> の左スワイプで <strong>ライブラリから削除</strong>／<strong>端末から削除</strong> の確認ダイアログ（一時的なクラウド検索プレビューでは無効）を開き、<strong>キュー</strong>・<strong>プレイリスト</strong>・<strong>お気に入り</strong> の左スワイプでは即時削除と <strong>元に戻す（Undo）</strong>（キュー位置・アクティブトラックインデックス・再生再開タイムスタンプを正確に復元）に対応。さらに Android ではフォルダのスワイプ削除しきい値を引き上げ（<code>~44%</code> / <code>min 140dp</code>）誤削除を防ぎます。</li><li><strong>統合設定の外観カスタマイズ＆デスクトップ向け機能：</strong> 統合された <strong>設定</strong>（<code>Cmd+,</code> / <code>Ctrl+,</code>）では、システム／ライト／ダークモード、厳選された背景＆アクセントプリセット、カスタム HEX/RGB/システムカラーピッカー、ライブの <strong>再生中プレビュー</strong>、ワンクリック <strong>コントラスト自動修正（Auto-fix Contrast）</strong> 付き内蔵 <strong>WCAG 2.1 コントラストチェック</strong>、および <strong>画像の可視性</strong>（不透明度）と <strong>背景のぼかし</strong> を調整できるカスタム背景画像を提供します。デスクトップ版ではさらにグローバルな <strong>コマンドパレット／クイックジャンプ</strong>（<code>Cmd+K</code> / <code>Ctrl+K</code>）、<strong>フローティング・ミニプレーヤー</strong> ウィンドウ（<code>Cmd+Shift+N</code> / <code>Ctrl+Shift+N</code>）、拡充されたキーボードショートカット（歌詞 <code>Cmd+Shift+L</code> / <code>Ctrl+Shift+L</code> / <code>L</code>、キュー <code>Cmd+Shift+Q</code> / <code>Ctrl+Shift+Q</code> / <code>Q</code>、シーク <code>±10秒</code>、音量 <code>±5%</code>、ミュート、シャッフル／リピート、再生中画面）を備えます。</li><li><strong>再生体験とライブラリ管理の細部：</strong><ul><li><strong>10 バンド ISO イコライザ</strong>（<code>31 Hz</code>–<code>16 kHz</code>、プリアンプ <code>-12 dB</code>〜<code>+12 dB</code>、8 プリセット + <code>Custom</code>）。</li><li><strong>同期歌詞・プレーン歌詞</strong>（<strong>インポート</strong> → <strong>サイドカー</strong> <code>.lrc</code>/<code>.txt</code> → <strong>埋め込みタグ</strong> の順で自動フォールバック、複数タイムスタンプ <code>.lrc</code> 解析、UTF-8 / UTF-16 BOM / GB18030 デコード、タップシーク、文字サイズ・配置のカスタマイズ、<strong>現在の行に同期</strong> 対応）。</li><li><strong>スリープタイマー・統計・タグ編集：</strong> <code>5</code>〜<code>90</code> 分または曲終了時停止タイマー、再生統計（<strong>最近</strong>、<strong>再生回数</strong>、<strong>最近聴いていない</strong>、<strong>未再生</strong> に加え <strong>トップアーティスト</strong> と <strong>トップアルバム</strong>）、インラインのメタデータ／カバーアート編集、OS メディアコントロール、<code>English</code> / <code>简体中文</code> の即時切り替え。</li></ul></li></ul><h2 id="クロスプラットフォーム-javascript-拡張" tabindex="-1">クロスプラットフォーム JavaScript 拡張 <a class="header-anchor" href="#クロスプラットフォーム-javascript-拡張" aria-label="Permalink to &quot;クロスプラットフォーム JavaScript 拡張&quot;">​</a></h2><p>コミュニティや個人向けの音楽ソースに対応するために重い WebView を組み込むのではなく、1 本の CommonJS スクリプト（<code>.musico.js</code>）または ZIP バンドル（<code>.musicoext</code>）を各プラットフォームのネイティブ JS ランタイム（Apple：<code>JavaScriptCore</code>、Android：<code>QuickJS</code>、Windows：<code>Jint</code>）内で直接実行します：</p><ul><li><strong>明示的な権限レビューと隔離されたサインイン：</strong> 新しくインポートした拡張は無効状態で保持され、宣言された <code>permissions.hosts</code> ドメイン許可リストや機能（<code>&quot;cookie&quot;</code>、<code>&quot;qr_login&quot;</code>、<code>&quot;web_login&quot;</code>、<code>&quot;tree&quot;</code>、<code>&quot;proxy&quot;</code> など）をユーザーが確認した後に有効化できます。<code>&quot;web_login&quot;</code> 機能と条件付きマニフェスト <code>webLogin</code>（<code>{ loginUrl, cookieDomains, requiredCookies?, userAgent? }</code>）を組み合わせると、プレーヤー UI を 100% ネイティブに保ったまま、サインインの Cookie 取得専用の隔離された一時 OS WebView（<strong>WKWebView</strong> / <strong>Android WebView</strong> / <strong>WebView2</strong>）が開きます。マスク表示付きの <code>cookies.txt</code> ファイルインポートにも対応しています。</li><li><strong>公式プラグインエコシステム（<code>v2026.11.26</code>）：</strong> 公式プラグインはすぐインポートできるバンドルとして提供され、<strong>YouTube Search</strong> <code>v1.2.0</code>（<code>web_login</code> + 音質ティア）、<strong>Bilibili Search</strong> <code>v1.2.0</code>（<code>qr_login</code> + Hi-Res/FLAC ティア）、<strong>NetEase Cloud Music</strong> <code>v1.2.0</code>（9 段階音質ティア + <code>qr_login</code>）、<strong>Apple Music</strong> <code>v1.0.1</code>（<code>searchLyrics</code> への Bearer トークン転送 + コーデック／アートワークフォールバック）を網羅しています。</li><li><strong>安全な運用とデバッグ：</strong> 拡張ごとの設定パネル、200 件のローリングログビューア、既存のライブラリ曲やキャッシュ済み音声を保持したままの非破壊的な無効化／アンインストール、そして拡張スクリプトをローカルで検証できる Node.js コンフォーマンスランナー（<code>docs/extensions/tools/mock-runner.mjs</code>）を備えています。</li></ul><h2 id="配布とリリースエンジニアリング" tabindex="-1">配布とリリースエンジニアリング <a class="header-anchor" href="#配布とリリースエンジニアリング" aria-label="Permalink to &quot;配布とリリースエンジニアリング&quot;">​</a></h2><p>マルチプラットフォーム対応の GitHub Actions ワークフローにより、すべてのターゲット向けにタグ付きリリース（最新 <code>v1.3.4</code>）を自動ビルド・テスト・公開しており、macOS Catalyst <code>.dmg</code>、iOS 未署名 <code>.ipa</code>、Android リリース／デバッグ <code>.apk</code>、Windows NSIS インストーラ（<code>Setup.exe</code>）および自己完結型ポータブル <code>.zip</code>（<code>portable.txt</code> 配置時は <code>.\\Data\\</code> に状態を保持）を生成します。Windows・Android・macOS には <code>SHA256SUMS.txt</code> 検証と <strong>バージョンをスキップ（Skip Version）</strong> に対応したアプリ内アップデータも組み込まれています。</p><h2 id="リポジトリとダウンロード" tabindex="-1">リポジトリとダウンロード <a class="header-anchor" href="#リポジトリとダウンロード" aria-label="Permalink to &quot;リポジトリとダウンロード&quot;">​</a></h2><ul><li><strong>ドキュメント＆プラグインハブ：</strong> <a href="https://musico.seanpnex.win/?lang=ja" target="_blank" rel="noreferrer">musico.seanpnex.win/?lang=ja</a>（ユーザーガイド・公式プラグイン・拡張 API v1）</li><li><strong>ソースコード：</strong> <a href="https://github.com/SEANPNEX/Musico" target="_blank" rel="noreferrer">github.com/SEANPNEX/Musico</a>（MIT License）</li><li><strong>リリース：</strong> <a href="https://github.com/SEANPNEX/Musico/releases/latest" target="_blank" rel="noreferrer">最新のデスクトップ／モバイル版ビルド</a></li><li><strong>拡張開発ガイド：</strong> <a href="https://musico.seanpnex.win/developers/?lang=ja" target="_blank" rel="noreferrer">musico.seanpnex.win/developers/?lang=ja</a> · <a href="https://github.com/SEANPNEX/Musico/blob/main/docs/extensions/README.md" target="_blank" rel="noreferrer">GitHub README</a></li></ul>',15))])}const A=t(i,[["render",a]]);export{S as __pageData,A as default};
